(18859, 'wd_malware_scanning_notification', '{\"title\":\"Malware Scanning - Notification\",\"slug\":\"malware-notification\",\"description\":\"Get email notifications when Defender has finished manual malware scans.\",\"status\":\"enabled\",\"type\":\"notification\",\"frequency\":\"\",\"day\":\"\",\"day_n\":\"0\",\"time\":\"\",\"in_house_recipients\":[],\"out_house_recipients\":[],\"dry_run\":false,\"configs\":{\"always_send\":\"\",\"error_send\":\"\",\"template\":{\"found\":{\"subject\":\"Malware Scan of {SITE_URL} is complete. {ISSUES_COUNT} issue(s) found.\",\"body\":\"Hi {USER_NAME},\\n\\nMalware Scan identified {ISSUES_COUNT} issue(s) on {SITE_URL}. The identified issue(s) is\\/are listed below.\\n\\n{ISSUES_LIST}\"},\"not_found\":{\"subject\":\"Scan of {SITE_URL} complete. {ISSUES_COUNT} issues found.\",\"body\":\"Hi {USER_NAME},\\n\\nNo vulnerabilities have been found for {SITE_URL}.\"},\"error\":{\"subject\":\"Couldn\\u2019t scan {SITE_URL} for vulnerabilities.\",\"body\":\"Hi {USER_NAME},\\n\\nWe couldn\\u2019t scan {SITE_URL} for vulnerabilities. Please visit your site and run a manual scan.\"}}},\"last_sent\":1705508937,\"est_timestamp\":0,\"next_run\":\"Never\",\"all_subscribers\":[]}', 'no'),
(18860, 'wd_malware_scanning_report', '{\"title\":\"Analyse des logiciels malveillants - Rapports\",\"slug\":\"malware-report\",\"description\":\"Ex\\u00e9cutez automatiquement des analyses r\\u00e9guli\\u00e8res de votre site et vous envoyez des rapports par e-mail.\",\"status\":\"enabled\",\"type\":\"report\",\"frequency\":\"weekly\",\"day\":\"sunday\",\"day_n\":\"1\",\"time\":\"4:00\",\"in_house_recipients\":[],\"out_house_recipients\":[],\"dry_run\":false,\"configs\":{\"always_send\":\"\",\"error_send\":false,\"template\":{\"found\":{\"subject\":\"Malware Scan of {SITE_URL} is complete. {ISSUES_COUNT} issue(s) found.\",\"body\":\"Hi {USER_NAME},\\r\\n\\r\\nMalware Scan identified {ISSUES_COUNT} issue(s) on {SITE_URL}. The identified issue(s) is\\/are listed below.\\r\\n\\r\\n{ISSUES_LIST}\"},\"not_found\":{\"subject\":\"Scan of {SITE_URL} complete. {ISSUES_COUNT} issues found.\",\"body\":\"Hi {USER_NAME},\\r\\n\\r\\nNo vulnerabilities have been found for {SITE_URL}.\"},\"error\":{\"subject\":\"Couldn\\u2019t scan {SITE_URL} for vulnerabilities. \",\"body\":\"Hi {USER_NAME},\\r\\n\\r\\nWe couldn\\u2019t scan {SITE_URL} for vulnerabilities. Please visit your site and run a manual scan.\"}}},\"last_sent\":1708830000,\"est_timestamp\":1709434800,\"next_run\":\"3 March 2024 4h00\",\"all_subscribers\":[]}', 'no'),
