DROP TABLE IF EXISTS `mod78_uap_action_logs_view`;

CREATE ALGORITHM=UNDEFINED DEFINER=`nparksf259`@`%` SQL SECURITY INVOKER VIEW `mod78_uap_action_logs_view`  AS SELECT `a`.`automator_action_id` AS `automator_action_id`, `a`.`date_time` AS `action_date`, `a`.`completed` AS `action_completed`, `a`.`error_message` AS `error_message`, `a`.`automator_recipe_id` AS `automator_recipe_id`, `a`.`ID` AS `action_log_id`, `a`.`automator_recipe_log_id` AS `recipe_log_id`, `r`.`date_time` AS `recipe_date_time`, `r`.`completed` AS `recipe_completed`, `r`.`run_number` AS `recipe_run_number`, `pa`.`post_title` AS `action_title`, `am`.`meta_value` AS `action_sentence`, `p`.`post_title` AS `recipe_title`, `u`.`ID` AS `user_id`, `u`.`user_email` AS `user_email`, `u`.`display_name` AS `display_name` FROM (((((`mod78_uap_action_log` `a` left join `mod78_uap_recipe_log` `r` on((`a`.`automator_recipe_log_id` = `r`.`ID`))) left join `mod78_posts` `p` on((`p`.`ID` = `a`.`automator_recipe_id`))) join `mod78_posts` `pa` on((`pa`.`ID` = `a`.`automator_action_id`))) left join `mod78_uap_action_log_meta` `am` on(((`a`.`automator_action_id` = `am`.`automator_action_id`) and (`am`.`automator_action_log_id` = `a`.`ID`) and (`am`.`user_id` = `a`.`user_id`) and (`am`.`meta_key` = 'sentence_human_readable_html')))) left join `mod78_users` `u` on((`a`.`user_id` = `u`.`ID`))) GROUP BY `a`.`ID` ;

